import inspect
import re

from typing import Callable, Type, TypedDict
from pydantic import BaseModel
from .schema import CommandMode


class Operation(TypedDict): 
    handler : Callable
    params_model : Type[BaseModel]
    is_async: bool
    mode : CommandMode

_registry: dict[str, dict[str, Operation]] = {}


def register_command(namespace: str, operation: str, mode: CommandMode):

    def decorator(func: Callable):

        ope : Operation = {}

        if not mode in [m for m in CommandMode]:
            raise TypeError("传入的mode参数必须是'CommandMode'类型的")

        ope["mode"] = mode

        #检测是否为异步函数。
        if inspect.iscoroutinefunction(func):
            ope["is_async"] = True
        else:
            ope["is_async"] = False

        #校验参数是否符合约定，在执行时，才校验参数是否符合定义的类型
        params_model = func.__annotations__

        if len(inspect.signature(func).parameters) != 1:
            raise TypeError("被注册的函数只能接受一个参数")

        elif not params_model.get("params"):
            raise TypeError("被注册的函数期望接受的参数名称为 'params' ")

        elif not issubclass(params_model.get("params"), BaseModel):
            raise TypeError("params 应该是 BaseModel 的子类")

        else:
            ope["params_model"] = params_model.get("params")
            ope["handler"] = func

        _registry.setdefault(namespace, {})[operation] = ope
        return func

    return decorator


#主要用法
chat_register = lambda operation, mode=CommandMode.PLAIN: register_command("chat", operation, mode)
config_register = lambda operation, mode=CommandMode.PLAIN: register_command("config", operation, mode)
approval_register = lambda operation, mode=CommandMode.PLAIN: register_command("approval", operation, mode)
session_register = lambda operation, mode=CommandMode.PLAIN: register_command("session", operation, mode)
diff_register = lambda operation, mode=CommandMode.PLAIN: register_command("diff", operation, mode)
skill_register = lambda operation, mode=CommandMode.PLAIN: register_command("skill", operation, mode)
mcp_register = lambda operation, mode=CommandMode.PLAIN: register_command("mcp", operation, mode)




#返回None表达没有注册该操作
def lookup(namespace_operation: str) -> Operation | None:

    pattern = r'^[^.]+[.].+$'
    if not re.match(pattern, namespace_operation):
        return None
    namespace, operation = namespace_operation.split(".", 1)
    return _registry.get(namespace, {}).get(operation)

def show_registry() -> list[str]:
    return [f"{ns}.{op}" for ns in _registry for op in _registry[ns]]

import asyncio
from typing import AsyncGenerator

from .executor import Executor
from .register import lookup

from .schema import (
    CommandMode,
    CommandProtocol,
    ErrorCode,
    make_event,
    make_receipt_error,
)

""" 对前端传来的commend进行调度 """

_executor = Executor()
_queues: dict[str, list[asyncio.Task]] = {}


def cancel_pending(conversation_id: str) -> None:

    queue = _queues.get(conversation_id)
    if not queue:
        return
    for task in queue:
        if not task.done():
            task.cancel()

def cancel_all() -> None:
    for queue in _queues.values():
        for task in queue:
            if not task.done():
                task.cancel()

async def submit(msg: CommandProtocol) -> AsyncGenerator:

    ###这里没有对operation进行检查后没有处理， 先进入队列进行排队， 可进行再一次优化###
    operation = lookup(msg.operation)

    mode = operation["mode"] if operation is not None else None

    # control 是对调度本身下命令：先清场再执行
    if mode == CommandMode.CONTROL:
        cancel_pending(msg.conversation_id)

    # plain / control（以及未注册操作，交给 Executor 回 UNKNOWN_OPERATION）直通
    if mode != CommandMode.WAIT:

        async for chunk in _executor.command_executor(
            msg.request_id, msg.operation, msg.conversation_id, msg.parameters,
        ):
            yield chunk
        return

    # 挂到本会话队列尾部，等前一个 wait 命令执行完
    # 需要wait

    task = asyncio.current_task()
    queue = _queues.setdefault(msg.conversation_id, [])
    prev = queue[-1] if queue else None
    queue.append(task)

    if prev is not None and not prev.done():
        yield make_event(
            msg.conversation_id,
            "run.queued",
            {"request_id": msg.request_id, "operation": msg.operation},
        )

        try:
            await prev
        except asyncio.CancelledError:
            # 前驱被取消则链条断掉，本命令未执行即结束
            yield make_receipt_error(
                msg.request_id,
                msg.conversation_id,
                ErrorCode.CANCELLED,
                "命令已受理，但在执行前被取消",
            )
            return
        except Exception:
            pass

    try:
        async for chunk in _executor.command_executor(
            msg.request_id, msg.operation, msg.conversation_id, msg.parameters,
        ):
            yield chunk

    finally:
        queue = _queues.get(msg.conversation_id)

        if queue is not None and task in queue:
            queue.remove(task)
            if not queue:
                _queues.pop(msg.conversation_id, None)

from __future__ import annotations

import json
from copy import deepcopy
from pathlib import Path
from typing import Any, Callable, ClassVar, Literal

from agentscope.credential import CredentialFactory
from agentscope.model import ChatModelBase

ThinkingLevel = Literal["off", "low", "medium", "high"]
_THINKING_LEVELS = frozenset({"off", "low", "medium", "high"})

# 与 backend 同级的 settings.json（测试用固定路径） 实际部署需要更改
_SETTINGS_PATH = Path(__file__).resolve().parents[2] / "settings.json"

# adapter 路由用：属于本模块的 config.set key
MODEL_CONFIG_KEYS = frozenset(
    {
        "provider",
        "model",
        "thinking_level",
        "context_size",
    },
)


def _empty_settings() -> dict[str, Any]:
    return {
        "provider_type": None,
        "credential": {},
        "model": None,
        "thinking_level": "off",
        "stream": True,
        "max_retries": 3,
        "context_size": 32768,
    }


class ModelConfig:
    """模型 / 凭证 / 思考等级 / 上下文窗口。"""

    _UPDATE_HANDLERS: ClassVar[
        dict[str, Callable[["ModelConfig", Any, Any], None]]
    ]

    def __init__(self) -> None:
        self._settings: dict[str, Any] = _empty_settings()
        self._load()

    def get(self) -> dict[str, Any]:
        """取出当前配置的公开视图（副本）。"""
        return self._public_view()

    def update(self, agent: Any = None, **patch: Any) -> dict[str, Any]:
        """统一更新入口：只做分支，业务在私有方法。"""
        if not patch:
            return self._public_view()

        unknown = set(patch) - set(self._UPDATE_HANDLERS)
        if unknown:
            raise KeyError(f"unknown model config key(s): {sorted(unknown)}")

        # provider 先于 model / thinking / context，避免半成品 build
        order = ("provider", "model", "thinking_level", "context_size")
        for key in order:
            if key not in patch:
                continue
            self._UPDATE_HANDLERS[key](self, patch[key], agent)

        if agent is not None and self._ready_to_build():
            self._mount(agent)

        self._save()
        return self._public_view()

    # ----- 分支：仅用户可配项 -----

    def _set_provider(self, value: Any, agent: Any) -> None:
        """provider_type 与 credential 一次写入。"""
        if not isinstance(value, dict):
            raise TypeError(
                "provider must be a dict like "
                '{"type": "openai_credential", "api_key": "...", ...}',
            )
        payload = dict(value)
        provider_type = payload.pop("type", None)
        if not provider_type:
            raise ValueError("provider requires key 'type' (credential type)")

        CredentialFactory.from_dict({"type": provider_type, **payload})

        self._settings["provider_type"] = provider_type
        self._settings["credential"] = payload

    def _set_model(self, value: Any, agent: Any) -> None:
        if not isinstance(value, str) or not value.strip():
            raise TypeError("model must be a non-empty str")
        self._settings["model"] = value.strip()

    def _set_thinking_level(self, value: Any, agent: Any) -> None:
        if value not in _THINKING_LEVELS:
            raise ValueError(
                f"thinking_level must be one of {sorted(_THINKING_LEVELS)}, "
                f"got {value!r}",
            )
        self._settings["thinking_level"] = value

    def _set_context_size(self, value: Any, agent: Any) -> None:
        if not isinstance(value, int) or isinstance(value, bool) or value <= 0:
            raise TypeError("context_size must be a positive int")
        self._settings["context_size"] = value

    # ----- 持久化：提供方 + API + 默认模型 -----

    def _load(self) -> None:
        """从 settings.json 读取；缺文件/缺字段/无效则保持空默认。"""
        path = _SETTINGS_PATH
        if not path.is_file():
            return

        try:
            raw = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return

        if not isinstance(raw, dict):
            return

        section = raw.get("model")
        if not isinstance(section, dict):
            return

        provider_type = section.get("provider_type")
        credential = section.get("credential")
        model_id = section.get("model")

        if not provider_type or not isinstance(provider_type, str):
            return
        if not isinstance(credential, dict):
            credential = {}
        if not model_id or not isinstance(model_id, str) or not model_id.strip():
            return

        try:
            CredentialFactory.from_dict({"type": provider_type, **credential})
        except Exception:
            return

        self._settings["provider_type"] = provider_type
        self._settings["credential"] = dict(credential)
        self._settings["model"] = model_id.strip()

    def _save(self) -> None:
        """将提供方 / API / 默认模型写回 settings.json（合并其它段）。"""
        path = _SETTINGS_PATH
        data: dict[str, Any] = {}
        if path.is_file():
            try:
                loaded = json.loads(path.read_text(encoding="utf-8"))
                if isinstance(loaded, dict):
                    data = loaded
            except (OSError, json.JSONDecodeError):
                data = {}

        provider_type = self._settings.get("provider_type")
        model_id = self._settings.get("model")
        if not provider_type or not model_id:
            # 未配齐则不写 model 段（或清空），保持文件其它内容
            data.pop("model", None)
        else:
            data["model"] = {
                "provider_type": provider_type,
                "credential": deepcopy(self._settings.get("credential") or {}),
                "model": model_id,
            }

        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(
            json.dumps(data, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )

    # ----- 构建 / 挂载 -----

    def _ready_to_build(self) -> bool:
        return bool(
            self._settings.get("provider_type")
            and self._settings.get("model"),
        )

    def _build_model(self) -> ChatModelBase:
        if not self._ready_to_build():
            raise RuntimeError(
                "model is not ready: set provider (with type+credential) "
                "and model first",
            )

        provider_type = self._settings["provider_type"]
        cred = CredentialFactory.from_dict(
            {"type": provider_type, **self._settings["credential"]},
        )
        model_cls = cred.get_chat_model_class()
        parameters = model_cls.Parameters(
            **self._parameters_kwargs(model_cls),
        )
        return model_cls(
            credential=cred,
            model=self._settings["model"],
            parameters=parameters,
            stream=self._settings["stream"],
            max_retries=self._settings["max_retries"],
            context_size=self._settings["context_size"],
        )

    def _parameters_kwargs(self, model_cls: type[ChatModelBase]) -> dict[str, Any]:
        """thinking_level → 该模型 Parameters 能接受的字段。"""
        level: ThinkingLevel = self._settings["thinking_level"]
        fields = model_cls.Parameters.model_fields
        kwargs: dict[str, Any] = {}

        if "thinking_enable" in fields:
            kwargs["thinking_enable"] = level != "off"

        if level == "off":
            return kwargs

        if "reasoning_effort" in fields:
            kwargs["reasoning_effort"] = level
        elif "thinking_budget" in fields:
            kwargs["thinking_budget"] = {
                "low": 1024,
                "medium": 8192,
                "high": 32768,
            }[level]

        return kwargs

    def _mount(self, agent: Any) -> None:
        agent.model = self._build_model()

    def _public_view(self) -> dict[str, Any]:
        cred = deepcopy(self._settings["credential"])
        if "api_key" in cred:
            raw = cred["api_key"]
            if hasattr(raw, "get_secret_value"):
                raw = raw.get_secret_value()
            text = str(raw) if raw is not None else ""
            cred["api_key"] = {
                "configured": bool(text),
                "suffix": text[-4:] if len(text) >= 4 else "",
            }

        return {
            "configured": self._ready_to_build(),
            "provider_type": self._settings["provider_type"],
            "credential": cred,
            "model": self._settings["model"],
            "thinking_level": self._settings["thinking_level"],
            "stream": self._settings["stream"],
            "max_retries": self._settings["max_retries"],
            "context_size": self._settings["context_size"],
        }

ModelConfig._UPDATE_HANDLERS = {
    "provider": ModelConfig._set_provider,
    "model": ModelConfig._set_model,
    "thinking_level": ModelConfig._set_thinking_level,
    "context_size": ModelConfig._set_context_size,
}

model_config = ModelConfig()

if __name__ == "__main__":
    print(model_config.get())
